import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const c=JSON.parse('{"title":"Частые вопросы","description":"","frontmatter":{"pageId":"faq","contentRevision":2},"headers":[],"relativePath":"ru/faq.md","filePath":"ru/faq.md"}'),s={name:"ru/faq.md"};function n(i,a,l,p,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="частые-вопросы" tabindex="-1">Частые вопросы <a class="header-anchor" href="#частые-вопросы" aria-label="Permalink to &quot;Частые вопросы&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Нужно ли играть одновременно?</strong> Нет для своих колоний и асинхронной экономики; да для live и совместной колонии.</p><p><strong>Можно ли продолжить офлайн?</strong> Каноническое состояние привязано к серверу. Не подменяй сейв локальной копией: это может конфликтовать с уже выданными предметами и сделками.</p><p><strong>Куда пропала отправка после обрыва?</strong> Сначала переподключись и проверь почту, рынок и состояние операции. Исходящий журнал повторяет неподтверждённый запрос с тем же идентификатором.</p><p><strong>Значит ли цвет союза владение территорией?</strong> Нет, это информационный слой добровольно опубликованного влияния.</p><h2 id="choosing" tabindex="-1">Нужен ли отдельный сервер и общий график? <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Нужен ли отдельный сервер и общий график? {#choosing}&quot;">​</a></h2><p><strong>Может ли один игрок просто пригласить другого без сервера?</strong> Rimlink использует выделенный сервер. Он может работать на отдельной машине или у участника, но должен быть доступен обеим играм. Браузерная панель — управление этим сервером, не сама игра.</p><p><strong>Нужно ли одновременно быть онлайн?</strong> Для торговли, сообщений, ожидающих рейдов и отдельных колоний — нет. Для live и coop — да: хозяин должен играть дома. Нельзя продолжить его колонию автономно после выхода.</p><p><strong>Можно ли делить всю колонию?</strong> Coop выдаёт управление явно назначенными пешками. Кошелёк, отправка вещей, административные полномочия и право записи сейва не передаются.</p><p><strong>Есть ли обязательная подписка?</strong> Мод и эта вики бесплатны. Копия игры, DLC и выбранный платный хостинг — отдельные расходы, не включённые в Rimlink.</p><h2 id="mistakes" tabindex="-1">Почему привычный обход проблемы опасен? <a class="header-anchor" href="#mistakes" aria-label="Permalink to &quot;Почему привычный обход проблемы опасен? {#mistakes}&quot;">​</a></h2><p><strong>Вернуть вещи старым сейвом?</strong> Нет: покупатель уже мог получить их. Сначала разреши исходную операцию через повтор/переподключение.</p><p><strong>Удалить outbox, чтобы убрать ошибку?</strong> Нет: это доказательство незавершённого запроса. Сохрани папку и диагностируй причину отказа.</p><p><strong>Принять изменённый сертификат, потому что сервер знакомый?</strong> Сначала проверь новый отпечаток у администратора отдельным каналом.</p><p><strong>Цвет гильдии запрещает вход?</strong> Нет. Влияние информационное, не владение землёй.</p><p><strong>Скриншоты в старом описании показывают игру?</strong> Концепт-арт показывает идею мода. В этой вики схемы не выдаются за реальный игровой UI; подтверждённая галерея игровых кадров пока не собрана.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Удаление журналов и повторная ручная выдача вещей могут создать потери или дублирование. При сомнении сообщи администратору время и id операции, а не пароль или токен.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/saves-recovery">Сохранения и восстановление</a></li><li><a href="./players/troubleshooting">Проблемы игрока</a></li><li><a href="./players/guild-influence">Влияние гильдий</a></li></ul>',22)])])}const u=e(s,[["render",n]]);export{c as __pageData,u as default};
